def spent_in_month(transactions: Iterable[Transaction], category: str, year: int, month: int) -> Decimal:
    """Net spending in category during the month as a positive amount.

    Refunds in the category reduce it; it never goes below zero.
    """
    net = sum(
        (-t.amount for t in transactions if t.category == category and (t.day.year, t.day.month) == (year, month)),
        ZERO,
    )
    return max(to_money(net), ZERO)

def occurrences(rule: RecurringRule, first: date, last: date) -> list[date]:
    """The dates between first and last (inclusive) on which rule is due, oldest first."""
    dates: list[date] = []
    for year, month in months_between(month_key(first), month_key(last)):
        due = date(year, month, rule.day_of_month)
        if first <= due <= last and rule.active_on(due):
            dates.append(due)
    return dates

