fixes.proposed:
def load_fleet(path: Path) -> Fleet:
    """Read a fleet written by :func:`save_fleet`."""
    try:
        raw = json.loads(path.read_text(encoding="utf-8"))
        if "vehicles" not in raw or "drivers" not in raw:
            raise KeyError("JSON file is missing 'vehicles' or 'drivers' key")
        fleet = Fleet()
        for item in raw["vehicles"]:
            fleet.add_vehicle(_vehicle_from(item))
        for item in raw["drivers"]:
            fleet.add_driver(_driver_from(item))
    except (json.JSONDecodeError, KeyError) as e:
        logger.exception("could not load the fleet from %s: %s", path, e)
        raise  # Re-raise the exception after logging
    return fleet

